1	export type Cell = [number, number]; // [x, y]
2	
3	const NEIGHBOR_OFFSETS: Cell[] = [
4	  [-1, -1],
5	  [-1, 0],
6	  [-1, 1],
7	  [0, -1],
8	  [0, 1],
9	  [1, -1],
10	  [1, 0],
11	  [1, 1],
12	];
