14	export function nextGeneration(liveCells: Cell[]): Cell[] {
15	  const alive = new Set(liveCells.map(keyOf));
16	
17	  return [...countLiveNeighbors(liveCells)]
18	    .filter(([key, liveNeighbors]) =>
19	      isAliveNextGeneration(liveNeighbors, alive.has(key)),
20	    )
21	    .map(([key]) => cellFrom(key));
22	}
23	
24	function isAliveNextGeneration(
25	  liveNeighbors: number,
26	  wasAlive: boolean,
27	): boolean {
28	  const survives = liveNeighbors === 2 || liveNeighbors === 3;
29	  const isBorn = liveNeighbors === 3;
30	
31	  return wasAlive ? survives : isBorn;
32	}
33	
34	function countLiveNeighbors(liveCells: Cell[]): Map<string, number> {
35	  const counts = new Map<string, number>();
36	
37	  for (const liveCell of liveCells) {
38	    for (const neighbor of neighborsOf(liveCell)) {
39	      const key = keyOf(neighbor);
40	
41	      counts.set(key, (counts.get(key) ?? 0) + 1);
42	    }
43	  }
44	
45	  return counts;
46	}
47	
48	function neighborsOf([x, y]: Cell): Cell[] {
49	  return NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
50	}
51	
52	function keyOf([x, y]: Cell): string {
53	  return `${x},${y}`;
54	}
55	
56	function cellFrom(key: string): Cell {
57	  const [x, y] = key.split(",").map(Number);
58	
59	  return [x, y];
60	}
